package cl.ipvg.georegistro;
import android.view.*; import android.widget.TextView; import androidx.annotation.*; import androidx.recyclerview.widget.*; import java.util.*;
public class IncidenciaAdapter extends RecyclerView.Adapter<IncidenciaAdapter.V>{List<Incidencia> l;IncidenciaAdapter(List<Incidencia>x){l=x;}public V onCreateViewHolder(@NonNull ViewGroup p,int t){return new V(LayoutInflater.from(p.getContext()).inflate(R.layout.item_incidencia,p,false));}public void onBindViewHolder(@NonNull V h,int p){Incidencia i=l.get(p);h.t.setText(i.getTitulo());h.c.setText("Categoría: "+i.getCategoria());h.f.setText("Fecha: "+i.getFechaHora());h.co.setText(String.format(Locale.US,"Ubicación: %.6f, %.6f",i.getLatitud(),i.getLongitud()));}public int getItemCount(){return l.size();}static class V extends RecyclerView.ViewHolder{TextView t,c,f,co;V(View v){super(v);t=v.findViewById(R.id.tvItemTitulo);c=v.findViewById(R.id.tvItemCategoria);f=v.findViewById(R.id.tvItemFecha);co=v.findViewById(R.id.tvItemCoordenadas);}}}